export async function prepareAvatar(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760)throw new Error('Choose a JPG, PNG or WebP image under 10 MB.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>40000000)throw new Error('Choose an image under 40 megapixels.');const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');ctx.fillStyle='#f0f4fa';ctx.fillRect(0,0,256,256);const side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);const data=canvas.toDataURL('image/jpeg',0.84).split(',')[1];if(data.length>262144)throw new Error('Photo is too large after resizing.');return data;}finally{bitmap.close();}}
